1	// The tasks the ENGINE itself ships (tasks-dispatch DESIGN §16.2), as opposed to
2	// the ones a declared pack contributes. There is exactly one: `implement-request`,
3	// the task a marked issue's work item names.
4	//
5	// It is a TASK rather than a special item shape because that is what keeps the
6	// request mode from being a second mechanism — the item's first body line is a task
7	// path validated in code like every other, the same-title mutex serializes twin
8	// requests, the janitor's leashes cover it, `verify-outcome` polices its ceiling and
9	// `record-exec` counts it. What follows from it being engine-owned rather than
10	// pack-owned is exactly two things, and they live here: task discovery gains this
11	// root beside the pack scan, and the validated task-path shape gains its form.
12	//
13	// It is not a pack and declares nothing. Wherever the queue runs it is active,
14	// which is also what fences the one field only it may declare
15	// (`model_from_request`): no pack can opt itself in, because no pack can be this.
16	
17	import { existsSync } from 'node:fs';
18	import { dirname, join, relative, sep } from 'node:path';
19	import { fileURLToPath } from 'node:url';
20	
21	// The id the built-in task's work items are titled with — `engine/implement-request`
22	// — in the same `<pack>/<task>` grammar as everything else, so nothing downstream
23	// needs a second parse.
24	export const BUILT_IN_PACK = 'engine';
25	export const REQUEST_TASK = 'implement-request';
26	export const REQUEST_TASK_ID = `${BUILT_IN_PACK}/${REQUEST_TASK}`;
27	
28	// Where this engine's own tasks live, resolved from THIS MODULE rather than probed
29	// against the repo: the engine root is wherever this file was vendored to, which is
30	// `engine/` in the canon and `.claudinite/shared/engine/` in a member, and asking
31	// the module cannot get that wrong the way a two-root probe can.
32	export const builtInTasksDir = () => join(dirname(fileURLToPath(import.meta.url)), 'queue', 'tasks');
33	
34	// The same directory as a path INSIDE the given repo root, or null when it is not
35	// inside it. Null is a real answer rather than an error: a test importing the canon
36	// engine against a fixture root is exactly that case, and the built-in task must
37	// then simply not be discovered there.
38	export function builtInTasksRoot(root) {
39	  const dir = builtInTasksDir();
40	  if (!existsSync(dir)) return null;
41	  const rel = relative(root, dir);
42	  if (!rel || rel.startsWith('..') || rel.startsWith(sep)) return null;
43	  return dir;
44	}
45	
46	// The request task's repo-relative worker path, in the form a work item's first
47	// line carries. Null where the engine is not inside this root (see above).
48	export function requestTaskPath(root) {
49	  const dir = builtInTasksRoot(root);
50	  return dir ? `${relative(root, join(dir, REQUEST_TASK)).split('\\').join('/')}/task.md` : null;
51	}
52	
53	// THE APPROVAL PHRASE. A comment beginning `/claude go` is how somebody with push
54	// access blesses an issue they did not open (DESIGN §16.4) — the blessing is the
55	// comment, never the mark. It lives here because two places need the same one: the
56	// `request` signal, which reads which logins wrote it, and the request task's
57	// precondition, which judges their permission.
58	export const APPROVAL_RE = /^\s*\/claude\s+go\b/im;
59	
