300	// The model a marked issue asks for, from the labels standing on it. An
301	// unrecognised family falls back to the default rather than failing the request:
302	// a run nobody can start would look accepted forever. Where several are present the
303	// order is REQUEST_MODELS' — the labels are consumed at adoption (§16.3), so the
304	// only way to hold two is to apply two for the same ask.
305	export const requestModelFromLabels = (labels = []) => {
306	  const asked = labels.filter((l) => l.startsWith(MODEL_LABEL_PREFIX)).map((l) => l.slice(MODEL_LABEL_PREFIX.length));
307	  return REQUEST_MODELS.find((f) => asked.includes(f)) ?? DEFAULT_REQUEST_MODEL;
308	};
