421	// --- comment markers ----------------------------------------------------------
422	// The three comments the protocol reads back. They are HTML comments so a human
423	// reading the item sees prose, and they are here — with the labels and the body
424	// fields — because together they ARE the item's vocabulary, the one compatibility
425	// surface across engine versions (DESIGN §14).
426	//
427	// The CLAIM comment carries who and when (executor identity is an unbounded set
428	// and must never become a label). The HANDOFF comment names the session and the
429	// invocation nonce. The EPISODE comment is the boundary the claim arbiter is
430	// scoped to: every claim before it is dead, and arbitrating over dead claims makes
431	// one outrank every future live claimant — the item then livelocks through reclaim
432	// cycles forever (F18). A reclaim, a revert and a hand re-queue each write one.
433	export const CLAIM_MARKER = '<!-- claudinite-claim -->';
434	export const HANDOFF_MARKER = '<!-- claudinite-handoff -->';
435	export const EPISODE_MARKER = '<!-- claudinite-episode -->';
436	
437	// --- the body -----------------------------------------------------------------
438	
439	export const NOT_BEFORE_FIELD = 'Not-before';
440	export const BLOCKED_BY_FIELD = 'Blocked-by';
441	
442	// The three fields a REQUEST item carries (DESIGN §16.3, §16.11). `Request` is the issue this
443	// run implements — the whole payload, since the request task has no code-work phase
444	// to hand one over. `Model` is the family the asker chose, copied here by the scheduler run
445	// from a write-gated label and read only by a task that declares
446	// `model_from_request`; it is the first thing an item carries that defines
447	// behaviour, which is why it is fenced rather than waved through (§16.7).
448	export const REQUEST_FIELD = 'Request';
449	export const MODEL_FIELD = 'Model';
450	
451	// `Task` is the TARGETING field (DESIGN §16, the one-issue request): which task a
452	// marked issue asks for, as `<pack>/<task>`. Absent, the ask is the built-in
453	// request implementer, which is what an ordinary "implement this issue" mark means.
454	// It rides the same author gate as `Model` and `Merge`: naming a task is choosing
455	// what runs, and a body is editable by whoever opened the issue.
456	export const TASK_FIELD = 'Task';
457	
458	// `Merge` is the asker's standing authorization, copied here from the
459	// write-gated `claude-automerge` label. Its one value is `if-narrow`: the run may
460	// land its own pull request when the diff classifier calls the diff narrow, and
461	// must park for approval otherwise. An absent field is the default — never merge —
462	// so an item an older scheduler run wrote reads as unauthorized rather than as authorized.
463	export const MERGE_FIELD = 'Merge';
464	export const MERGE_IF_NARROW = 'if-narrow';
465	
466	// The heading the delivered-artifacts section carries in a work item body. One
467	// home, because it is written in three places and MATCHED when a re-entrant run
468	// updates the section it already wrote.
469	export const DELIVERED_HEADING = 'Delivered by code-work';
470	
471	// The same heading as earlier renames spelled it. A live item's body still carries
472	// whichever word was current when its section was first written, and matching only
473	// today's would append a SECOND section rather than updating that one.
474	export const LEGACY_DELIVERED_HEADINGS = Object.freeze([
475	  'Delivered by prework',
476	  'Delivered by code_work',
477	]);
478	
479	// --- the machine block (DESIGN §16.1, §16.3) ----------------------------------
480	// A one-issue request's item IS the issue somebody marked, so the item's fields
481	// share a body a person authored and keeps editing. They live in one delimited
482	// block, appended at adoption and rewritten in place after that: everything outside
483	// it belongs to the human, everything inside it to the machine, and a parser that
484	// read the whole body would take a sentence of prose for a field.
485	//
486	// A `[claudinite-work]` item has no block — its whole body is the machine's — so
487	// every reader here falls back to the whole text, which is what keeps items filed
488	// before the one-issue model draining unchanged.
489	export const MACHINE_BLOCK_START = '<!-- claudinite-item -->';
490	export const MACHINE_BLOCK_END = '<!-- /claudinite-item -->';
491	
492	const BLOCK_RE = /<!-- claudinite-item -->\n?([\s\S]*?)\n?<!-- \/claudinite-item -->/;
493	
494	// The machine's half of a body, or null where there is no block at all.
495	export const machineBlockOf = (body) => BLOCK_RE.exec(String(body ?? ''))?.[1] ?? null;
496	
497	// The machine's half to read fields out of: the block where there is one, the whole
498	// body otherwise.
499	export const itemFieldText = (body) => machineBlockOf(body) ?? String(body ?? '');
500	
501	// Replace the block, or append one to a body that has none. The human's text is
502	// never rewritten — an append lands after it, separated by a blank line.
503	export function withMachineBlock(body, block) {
504	  const text = String(body ?? '');
505	  const wrapped = `${MACHINE_BLOCK_START}\n${block.replace(/\s*$/, '')}\n${MACHINE_BLOCK_END}`;
506	  if (BLOCK_RE.test(text)) return text.replace(BLOCK_RE, wrapped);
507	  return `${text.replace(/\s*$/, '')}\n\n${wrapped}\n`;
508	}
509	
510	// Apply an edit to whichever half is the machine's. Every writer that reshapes an
511	// item body — a Context section, code-work's delivered list, a stamped
512	// `Not-before` — goes through here, so it edits the block on a marked issue and the
513	// whole body on a `[claudinite-work]` item, with one call site either way.
514	export function editItemBody(body, edit) {
515	  const block = machineBlockOf(body);
516	  return block === null ? edit(String(body ?? '')) : withMachineBlock(body, edit(block));
517	}
518	
519	// The human's half of a body — everything the machine block is not. A marked
520	// issue's PARAMETERS are read from here and never from the block: re-asking clears
521	// the status and leaves the previous run's block standing, and a parser that read
522	// the whole body would find that stale copy beside the person's own field.
523	export const humanTextOf = (body) => String(body ?? '').replace(BLOCK_RE, '').trim();
524	
525	const NOT_BEFORE_RE = /^Not-before:[ \t]*(.*)$/m;
526	const BLOCKED_BY_RE = /^Blocked-by:[ \t]*(.*)$/m;
527	const REQUEST_RE = /^Request:[ \t]*#?(\d+)/m;
528	const MODEL_RE = /^Model:[ \t]*(\S+)/m;
529	const MERGE_RE = /^Merge:[ \t]*(\S+)/m;
530	
531	// Build a work item body. The first line is the task path — the only thing an
532	// executor reads to locate the worker, validated in code before anything trusts
533	// it. Everything behavior-defining (model, ceiling, worker content, code-work
534	// command) is read from the tracked task files at HEAD, never from here.
535	export function workItemBody({
536	  taskPath, notBefore = null, blockedBy = [], context = [], delivered = [], reason = null,
537	  request = null, model = null, merge = null,
538	}) {
539	  const lines = [taskPath, ''];
540	  const fields = [];
541	  if (notBefore) fields.push(`${NOT_BEFORE_FIELD}: ${notBefore}`);
542	  if (blockedBy.length) fields.push(`${BLOCKED_BY_FIELD}: ${blockedBy.map((n) => `#${n}`).join(', ')}`);
543	  if (request) fields.push(`${REQUEST_FIELD}: #${request}`);
544	  if (model) fields.push(`${MODEL_FIELD}: ${model}`);
545	  if (merge) fields.push(`${MERGE_FIELD}: ${merge}`);
546	  if (fields.length) lines.push(...fields, '');
547	  lines.push('Execute the Claudinite task above.');
548	  if (context.length) {
549	    lines.push(
550	      'The Context section below is binding scope — do not re-decide it.',
551	      '',
552	      '### Context',
553	      ...context.map((c) => `- ${c}`),
554	    );
555	  }
556	  if (reason) lines.push('', '### Why the agent is here', '', `- ${reason}`);
557	  if (delivered.length) lines.push('', `### ${DELIVERED_HEADING}`, '', ...delivered.map((d) => `- ${d}`));
558	  return lines.join('\n') + '\n';
559	}
560	
561	// The `Blocked-by` numbers a body names, from a work item's body or from an
562	// ORDINARY issue's — a request marked for implementation states what it waits on in
563	// the same field spelling, and adoption carries it onto the item it births (§16.11).
564	export function parseBlockedBy(body) {
565	  const bb = BLOCKED_BY_RE.exec(String(body ?? ''))?.[1] ?? '';
566	  return [...bb.matchAll(/#(\d+)/g)].map((m) => Number(m[1]));
567	}
568	
569	// Parse an item body back into the facts the scheduler run and the executor read. A body
570	// with no first line, or whose fields are absent, yields nulls — absence is
571	// meaningful everywhere here and is never filled in with a default.
572	export function parseWorkItemBody(body) {
573	  const text = itemFieldText(body);
574	  const taskPath = text.split('\n').map((l) => l.trim()).find((l) => l !== '') ?? null;
575	  const nb = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
576	  const blockedBy = parseBlockedBy(text);
577	  const request = REQUEST_RE.exec(text) ? Number(REQUEST_RE.exec(text)[1]) : null;
578	  // An unrecognised family reads as absent rather than as itself: the item's model
579	  // is behaviour-defining, so the only values that leave this parser are ones the
580	  // engine can actually dispatch at (§16.7).
581	  const askedModel = MODEL_RE.exec(text)?.[1] ?? null;
582	  const model = REQUEST_MODELS.includes(askedModel) ? askedModel : null;
583	  // Same fencing as the model: an unrecognised authorization reads as absent, and
584	  // absent is the safe end of this field — a run that cannot read its permission
585	  // opens a pull request and waits.
586	  const askedMerge = MERGE_RE.exec(text)?.[1] ?? null;
587	  const merge = askedMerge === MERGE_IF_NARROW ? askedMerge : null;
588	  return { taskPath, notBefore: nb, blockedBy, request, model, merge };
589	}
590	
591	// WHAT A MARKED ISSUE ASKS FOR (DESIGN §16.3, §16.7, §16.11) — read from the
592	// person's own text at every adoption, so each ask names its parameters afresh and
593	// nothing stale outranks a new one.
594	//
595	// `gated` is whether the issue's AUTHOR holds push access. A body is editable by
596	// whoever opened the issue where a label was write-gated by the platform, so the
597	// three behaviour-defining fields are honoured only for an author who could have
598	// applied them as labels anyway; an ungated ask still runs, at the default task and
599	// model and with no authorization to land anything.
600	export function parseRequestFields(body, { gated = false } = {}) {
601	  const text = humanTextOf(body);
602	  const asked = {
603	    task: /^Task:[ \t]*(\S+)/m.exec(text)?.[1] ?? null,
604	    model: MODEL_RE.exec(text)?.[1] ?? null,
605	    automerge: /^Automerge:[ \t]*(\S+)/m.exec(text)?.[1]?.toLowerCase() ?? null,
606	  };
607	  const blockedBy = parseBlockedBy(text);
608	  const notBefore = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
609	  if (!gated) return { task: null, model: null, merge: null, blockedBy, notBefore, ungated: Object.values(asked).some(Boolean) };
610	  return {
611	    task: /^[^/\s]+\/[^/\s]+$/.test(asked.task ?? '') ? asked.task : null,
612	    // An unrecognised family reads as absent rather than failing the request: a run
613	    // nobody can start would look accepted forever.
614	    model: REQUEST_MODELS.includes(asked.model) ? asked.model : null,
615	    merge: ['if-narrow', 'yes', 'true'].includes(asked.automerge) ? MERGE_IF_NARROW : null,
616	    blockedBy,
617	    notBefore,
618	    ungated: false,
619	  };
620	}
621	
622	// The item's own `### Context` bullets, in order — the binding scope a hand-created
623	// item was born with. Read back rather than kept only for the agent to read,
624	// because an operator's PARAMETERS ride here: `create-work-item --context
625	// "REPOS=Alpha Beta"` is how a forced run says what it is running on, and the
626	// executor hands these lines to code-work as `CLAUDINITE_CONTEXT`.
627	//
628	// A section runs to the next `### ` heading or to the end of the body — the same
629	// bounds `withSection` writes to — and only `- ` bullets count, so the prose
630	// framing around a section contributes nothing.
631	function sectionLines(body, heading) {
632	  const lines = String(body ?? '').split('\n');
633	  const at = lines.findIndex((l) => l.trim() === `### ${heading}`);
634	  if (at === -1) return [];
635	  const out = [];
636	  for (const line of lines.slice(at + 1)) {
637	    if (line.startsWith('### ')) break;
638	    const m = /^-[ \t]+(.*)$/.exec(line);
639	    if (m) out.push(m[1].trim());
640	  }
641	  return out;
642	}
643	
644	export const parseContextLines = (body) => sectionLines(body, 'Context');
645	
646	// --- the roll's record ----------------------------------------------------------
647	
648	// The section a no-go roll keeps on the item: the last declined reason and the next
649	// wake, REPLACED on every roll (the item is a status line, not a log — the timeline
650	// carries the history). Serializer and parser live together so the shape has one
651	// home; the executor writes it, and anything answering "why didn't it run" — the
652	// dashboard above all — reads it back.
653	export const LAST_VERDICT_HEADING = 'Last verdict';
654	
655	export function lastVerdictLines({ at, reason, until }) {
656	  const lines = [`${at} — the precondition declined: ${reason}`];
657	  if (until) lines.push(`Asked again at ${until}.`);
658	  return lines;
659	}
660	
661	export function parseLastVerdict(body) {
662	  const lines = sectionLines(body, LAST_VERDICT_HEADING);
663	  // The reason may carry the separator itself, so the split is on the FIRST match.
664	  const first = /^(.*?) — the precondition declined: ([\s\S]*)$/.exec(lines[0] ?? '');
665	  if (!first) return null;
666	  const until = lines.map((l) => /^Asked again at (.*?)\.?$/.exec(l)).find(Boolean)?.[1] ?? null;
667	  return { at: first[1], reason: first[2], until };
668	}
669	
670	// Fold a second set of Context lines into the first, keeping order and dropping
671	// exact duplicates. Both sides are real scope — the item carries what its creator
672	// bound it to, the precondition adds what this occurrence found — and a set-write
673	// from either side would drop the other's.
674	export const mergeContext = (...groups) => [...new Set(groups.flat().filter((l) => l && l.trim()))];
675	
676	// Stamp (or clear) `Not-before` on an existing body, in place where the field is
677	// already present and directly under the task path otherwise. Text surgery rather
678	// than a rebuild: the body also carries the creating precondition's Context and
679	// code-work's Delivered section, which belong to whoever wrote them.
680	export function withNotBefore(body, iso) {
681	  const text = String(body ?? '');
682	  if (NOT_BEFORE_RE.test(text)) {
683	    return iso
684	      ? text.replace(NOT_BEFORE_RE, `${NOT_BEFORE_FIELD}: ${iso}`)
685	      : text.replace(/^Not-before:[ \t]*.*\n?/m, '');
686	  }
687	  if (!iso) return text;
688	  const lines = text.split('\n');
689	  const at = lines.findIndex((l) => l.trim() !== '');
690	  if (at === -1) return `${NOT_BEFORE_FIELD}: ${iso}\n`;
691	  lines.splice(at + 1, 0, '', `${NOT_BEFORE_FIELD}: ${iso}`);
692	  return lines.join('\n');
693	}
694	
695	// Set a section of an item body (the Context, code-work's Delivered, the agent's Why)
696	// — replacing one of the same heading if it is already there, appending otherwise.
697	//
698	// REPLACING IS THE WHOLE POINT, and appending was a live bug (#879). Every standing
699	// item is born carrying a `### Context`, and the hand-off writes Context again — so
700	// an append leaves TWO sections of that name, while the session is told to read "the
701	// issue's Context section", singular. The one it reads first is then the scheduler run's birth
702	// note and the binding scope is in the other, which fails silently whichever section
703	// the agent picks. It also grows: an item re-queued through hand-off twice carried a
704	// third.
705	//
706	// A section runs to the next `### ` heading or to the end of the body, so a replaced
707	// section keeps its position rather than migrating to the bottom — the body stays in
708	// the order a reader learned it.
709	// `aliases` are older spellings of the SAME heading. The section is rewritten under
710	// `heading`, but located by any of them, so a body written before a rename is updated
711	// in place instead of gaining a second section.
712	export function withSection(body, heading, lines, aliases = []) {
713	  if (!lines.length) return body;
714	  const text = String(body ?? '').replace(/\s*$/, '');
715	  const section = [`### ${heading}`, '', ...lines.map((l) => `- ${l}`)];
716	  const existing = text.split('\n');
717	  const wanted = new Set([heading, ...aliases].map((h) => `### ${h}`));
718	  const at = existing.findIndex((l) => wanted.has(l.trim()));
719	  if (at === -1) return `${text}\n\n${section.join('\n')}\n`;
720	  const after = existing.findIndex((l, i) => i > at && l.startsWith('### '));
721	  const tail = after === -1 ? [] : ['', ...existing.slice(after)];
722	  return `${[...existing.slice(0, at), ...section, ...tail].join('\n')}\n`;
723	}
